import json, sys
data = json.load(sys.stdin)
for entry in data['Results']['series'][0]['data']:
    if entry['year'] in ['1960', '1961', '1962'] and entry['period'] == 'M13':
        print(f\"Year: {entry['year']}, Annual Average CPI-U: {entry['value']}\")
    elif entry['year'] in ['1960', '1961', '1962']:
        print(f\"Year: {entry['year']}, Period: {entry['period']} ({entry['periodName']}), Value: {entry['value']}\")
"

